INSERT INTO products (name, description, price, original_price, image_url, category_id, stock, active, featured, source_url) VALUES
('Chapéu de Feltro Alpaca Santa Fé II Pralana 30764', 'Chapéu de Feltro Alpaca Santa Fé II da marca Pralana, ref. 30764. Feltro de alpaca premium com acabamento sofisticado, copa moldada e aba reta. Carneira em material sintético para melhor firmeza e ajuste. Garantia de 90 dias pelo fabricante. Disponível na Agro Brasil.', 445.20, NULL, 'https://cdn.iset.io/assets/66687/produtos/16382/chapeu-de-feltro-alpaca-santa-fe-ii-pralana-30764.jpg', '6c6c18c3-07ae-42f1-a196-c0e81f1f237b', 10, true, false, 'https://www.rodeowest.com.br/chapeu-de-feltro-alpaca-santa-fe-ii-pralana-30764-p16382'),
('Chapéu Social Feltro Marrom 5X Jubileu Pralana 27907', 'Chapéu Social em Feltro Marrom 5X Jubileu da marca Pralana, ref. 27907. Modelo social elegante em feltro de qualidade, ideal para eventos e uso diário. Carneira em material sintético para conforto e ajuste perfeito. Garantia de 90 dias pelo fabricante. Disponível na Agro Brasil.', 308.33, NULL, 'https://cdn.iset.io/assets/66687/produtos/14344/chapeu-social-feltro-marrom-5x-jubileu-pralana-27907.jpg', '6c6c18c3-07ae-42f1-a196-c0e81f1f237b', 12, true, false, 'https://www.rodeowest.com.br/chapeu-social-feltro-marrom-5x-jubileu-pralana-27907-p14344'),
('Chapéu Country Pralana Preto 35074', 'Chapéu Country da marca Pralana na cor preta, ref. 35074. Modelo country clássico em feltro resistente, aba moldável e copa tradicional. Carneira em material sintético para firmeza e ajuste. Garantia de 90 dias pelo fabricante. Disponível na Agro Brasil.', 338.31, NULL, 'https://cdn.iset.io/assets/66687/produtos/19168/chapeu-country-pralana-preto-35074.jpg', '6c6c18c3-07ae-42f1-a196-c0e81f1f237b', 8, true, false, 'https://www.rodeowest.com.br/chapeu-country-pralana-preto-35074-p19168'),
('Chapéu de Feltro Country 7X Preto Stetson 574.70', 'Chapéu de Feltro Country 7X da marca Stetson na cor preta. Feltro premium com acabamento superior, aba larga e copa cattleman. Carneira em material sintético para firmeza e ajuste. Banda em couro costurado. Garantia de 90 dias pelo fabricante. Disponível na Agro Brasil.', 574.70, NULL, 'https://cdn.iset.io/assets/66687/produtos/21650/stetson-feltro-7x-preto.jpg', '6c6c18c3-07ae-42f1-a196-c0e81f1f237b', 6, true, true, 'https://www.rodeowest.com.br/q/stetson'),
('Chapéu Stetson Palha 20X Natural 37984', 'Chapéu Country modelo 20X da marca Stetson, fabricado em palha estilo shantung com aba de 11cm e copa de 12,5cm. Carneira de material sintético que proporciona melhor firmeza e ajuste. A banda que envolve a copa é fabricada em couro costurado na cor marrom dando um toque discreto ao modelo. Ref. 37984. Garantia de 90 dias pelo fabricante. Disponível na Agro Brasil.', 824.58, NULL, 'https://cdn.iset.io/assets/66687/produtos/21650/25a936d66f7ace2cc31dcdad4204909667e803c78d595.png', '6c6c18c3-07ae-42f1-a196-c0e81f1f237b', 5, true, true, 'https://www.rodeowest.com.br/chapeu-de-palha-natural-stetson-37984-p21650'),
('Chapéu Stetson Gold Edition 100X', 'Chapéu Stetson Gold Edition 100X, o mais premium da linha Stetson. Feltro de altíssima qualidade com acabamento luxuoso. Copa e aba com moldagem perfeita. Carneira premium e banda em couro fino. Peça exclusiva para colecionadores e amantes do estilo western. Garantia de 90 dias pelo fabricante. Disponível na Agro Brasil.', 1926.51, NULL, 'https://cdn.iset.io/assets/66687/produtos/stetson-gold-100x.jpg', '6c6c18c3-07ae-42f1-a196-c0e81f1f237b', 3, true, true, 'https://www.rodeowest.com.br/q/stetson'),
('Chapéu de Palha Country Mundial 10X', 'Chapéu de Palha Country da marca Mundial, modelo 10X. Palha natural resistente e leve, ideal para trabalho e lazer. Aba larga para proteção solar. Carneira em material sintético. Garantia de 90 dias pelo fabricante. Disponível na Agro Brasil.', 299.52, NULL, 'https://cdn.iset.io/assets/66687/produtos/mundial-palha-10x.jpg', '6c6c18c3-07ae-42f1-a196-c0e81f1f237b', 15, true, false, 'https://www.rodeowest.com.br/q/mundial'),
('Chapéu de Palha Shantung Aba Larga Natural', 'Chapéu de Palha Shantung com aba larga na cor natural. Leve e ventilado, perfeito para dias quentes no campo. Acabamento artesanal com fita decorativa. Garantia de 90 dias pelo fabricante. Disponível na Agro Brasil.', 246.30, NULL, 'https://cdn.iset.io/assets/66687/produtos/chapeu-palha-shantung-natural.jpg', '6c6c18c3-07ae-42f1-a196-c0e81f1f237b', 20, true, false, 'https://www.rodeowest.com.br/homens/chapeus-e-bones/chapeus-palha/'),
('Chapéu de Palha Bangora Preto Country', 'Chapéu de Palha Bangora na cor preta, estilo country moderno. Palha trançada resistente com copa moldada. Carneira confortável e banda decorativa. Garantia de 90 dias pelo fabricante. Disponível na Agro Brasil.', 194.01, NULL, 'https://cdn.iset.io/assets/66687/produtos/chapeu-bangora-preto.jpg', '6c6c18c3-07ae-42f1-a196-c0e81f1f237b', 18, true, false, 'https://www.rodeowest.com.br/homens/chapeus-e-bones/chapeus-palha/'),
('Chapéu de Feltro Country Americano Preto', 'Chapéu de Feltro Country estilo Americano na cor preta. Feltro de qualidade com aba larga e copa alta. Modelo clássico para cowboys. Carneira em material sintético. Garantia de 90 dias pelo fabricante. Disponível na Agro Brasil.', 365.03, NULL, 'https://cdn.iset.io/assets/66687/produtos/chapeu-americano-preto.jpg', '6c6c18c3-07ae-42f1-a196-c0e81f1f237b', 10, true, false, 'https://www.rodeowest.com.br/q/chapeu+americano'),
('Chapéu de Feltro Country Americano Marrom', 'Chapéu de Feltro Country estilo Americano na cor marrom. Feltro premium com acabamento refinado, aba modelável. Ideal para rodeios e eventos. Carneira confortável. Garantia de 90 dias pelo fabricante. Disponível na Agro Brasil.', 365.03, NULL, 'https://cdn.iset.io/assets/66687/produtos/chapeu-americano-marrom.jpg', '6c6c18c3-07ae-42f1-a196-c0e81f1f237b', 10, true, false, 'https://www.rodeowest.com.br/q/chapeu+americano'),
('Chapéu de Feltro Cinza Country 10X', 'Chapéu de Feltro Cinza Country modelo 10X. Feltro de qualidade na cor cinza, estilo moderno e elegante. Copa cattleman e aba reta. Carneira em material sintético. Garantia de 90 dias pelo fabricante. Disponível na Agro Brasil.', 349.08, NULL, 'https://cdn.iset.io/assets/66687/produtos/chapeu-feltro-cinza-10x.jpg', '6c6c18c3-07ae-42f1-a196-c0e81f1f237b', 12, true, false, 'https://www.rodeowest.com.br/q/chapeu+cinza'),
('Chapéu Stetson Feltro Marrom 6X', 'Chapéu Stetson em Feltro Marrom modelo 6X. Qualidade superior da marca Stetson com acabamento impecável. Aba larga e copa tradicional. Banda em couro costurado. Garantia de 90 dias pelo fabricante. Disponível na Agro Brasil.', 536.39, NULL, 'https://cdn.iset.io/assets/66687/produtos/stetson-feltro-marrom-6x.jpg', '6c6c18c3-07ae-42f1-a196-c0e81f1f237b', 7, true, true, 'https://www.rodeowest.com.br/q/stetson'),
('Chapéu Stetson Feltro Preto 4X', 'Chapéu Stetson em Feltro Preto modelo 4X. Entrada da linha Stetson com excelente custo-benefício. Feltro resistente, copa moldada e aba reta. Banda decorativa. Garantia de 90 dias pelo fabricante. Disponível na Agro Brasil.', 440.60, NULL, 'https://cdn.iset.io/assets/66687/produtos/stetson-feltro-preto-4x.jpg', '6c6c18c3-07ae-42f1-a196-c0e81f1f237b', 9, true, false, 'https://www.rodeowest.com.br/q/stetson'),
('Chapéu de Feltro Preto Reto Country', 'Chapéu de Feltro Preto modelo Reto Country. Feltro de qualidade com copa reta e aba larga. Estilo moderno para o cowboy contemporâneo. Carneira confortável. Garantia de 90 dias pelo fabricante. Disponível na Agro Brasil.', 349.08, NULL, 'https://cdn.iset.io/assets/66687/produtos/chapeu-feltro-preto-reto.jpg', '6c6c18c3-07ae-42f1-a196-c0e81f1f237b', 14, true, false, 'https://www.rodeowest.com.br/q/chapeu+reto')